import { useId, useState } from 'react';
import {
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
  JxToast,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'Только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'Может править' },
  { value: 'admin', label: 'Администратор', meta: 'Полный доступ' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const isValid = EMAIL_RE.test(email.trim());
  const errorText =
    touched && !isValid
      ? email.trim().length === 0
        ? 'Введите адрес почты'
        : 'Это не похоже на адрес почты. Пример: name@company.com'
      : undefined;

  const headingId = useId();

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <section
      aria-labelledby={headingId}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        maxWidth: 420,
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <h2
        id={headingId}
        style={{ margin: 0, fontFamily: 'var(--jx-font-display)' }}
      >
        Пригласить в команду
      </h2>

      {invited && (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`${invited} получит письмо со ссылкой на вступление.`}
          onClose={() => setInvited(null)}
        />
      )}

      <form
        onSubmit={submit}
        noValidate
        style={{ display: 'flex', flexDirection: 'column', gap: 16 }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          name="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Приглашение действует 7 дней"
          errorText={errorText}
        />

        <JxSelect
          label="Роль"
          options={ROLES}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: 8 }}>
          <JxButton type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </section>
  );
}

